frappe.listview_settings['Candidate'] = {
    onload: function(listview) {
        listview.page.add_action_item('Schedule Interview', function() {
            var selected_candidates = listview.get_checked_items();
            if (selected_candidates.length === 1) {
                var candidate_name = selected_candidates[0].name;
                frappe.new_doc("Interview", { "candidate": candidate_name });
            } else {
                frappe.msgprint("Please select one candidate to schedule an interview.");
            }
        });
    }
};

// Custom Script for Interview List View
frappe.listview_settings['Interview'] = {
    onload: function(listview) {
        listview.page.add_action_item(__('Get Questions'), function() {
            const selected = listview.get_checked_items();
            if (selected.length > 0) {
                selected.forEach(item => {
                    frappe.call({
                        method: 'interview_app.interview_app.doctype.question.question.get_questions',
                        args: {
                            candidate: item.candidate  // Ensure this matches the candidate field in the Interview doctype
                        },
                        callback: function(r) {
                            if (r.message && r.message.length > 0) {
                                let questions = r.message;
                                let questions_html = '<ol>';
                                questions.forEach(q => {
                                    questions_html += `<li>${q.questions}</li>`;
                                });
                                questions_html += '</ol>';
                                frappe.msgprint({
                                    title: 'Interview Questions for ' + item.candidate,
                                    indicator: 'blue',
                                    message: questions_html
                                });
                            } else {
                                frappe.msgprint({
                                    title: 'No Questions',
                                    indicator: 'red',
                                    message: 'No questions found for this candidate.'
                                });
                            }
                        }
                    });
                });
            } else {
                frappe.msgprint({
                    title: 'No Selection',
                    indicator: 'orange',
                    message: 'Please select an interview to get questions.'
                });
            }
        });
    }
};
